SELECT sm.sm_type AS ship_mode_type, sm.sm_carrier AS carrier, SUM(cs.cs_net_paid) AS total_catalog_net_paid, AVG(ws.ws_net_paid) AS avg_web_net_paid FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN web_sales ws ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_sold_date_sk = 2450817 AND ws.ws_sold_date_sk = 2452377 GROUP BY sm.sm_type, sm.sm_carrier
